import React from 'react';
import { NavLink } from 'react-router-dom';
import { useCart } from '../context/CartContext';
import { useWishlist } from '../context/WishlistContext';

function BottomNav() {
  const { totalCount } = useCart();
  const { totalWishlistCount } = useWishlist();

  return (
    <nav className="mobile-bottom-nav d-lg-none py-1">
      <div className="d-flex justify-content-around align-items-center">
        <NavLink
          to="/"
          end
          className={({ isActive }) => `mobile-nav-btn ${isActive ? 'active' : ''}`}
        >
          <i className="bi bi-house-door-fill"></i>
          <span>Home</span>
        </NavLink>

        <NavLink
          to="/products"
          className={({ isActive }) => `mobile-nav-btn ${isActive ? 'active' : ''}`}
        >
          <i className="bi bi-grid-fill"></i>
          <span>Categories</span>
        </NavLink>

        <NavLink
          to="/products?filter=wishlist"
          className={({ isActive }) => `mobile-nav-btn position-relative ${isActive ? 'active' : ''}`}
        >
          <div className="position-relative d-inline-block">
            <i className="bi bi-heart-fill"></i>
            {totalWishlistCount > 0 && (
              <span className="position-absolute top-0 start-100 translate-middle badge rounded-pill bg-danger border border-white" style={{ fontSize: '0.6rem' }}>
                {totalWishlistCount}
              </span>
            )}
          </div>
          <span>Wishlist</span>
        </NavLink>

        <NavLink
          to="/cart"
          className={({ isActive }) => `mobile-nav-btn position-relative ${isActive ? 'active' : ''}`}
        >
          <div className="position-relative d-inline-block">
            <i className="bi bi-bag-fill"></i>
            {totalCount > 0 && (
              <span className="position-absolute top-0 start-100 translate-middle badge rounded-pill bg-danger border border-white" style={{ fontSize: '0.6rem' }}>
                {totalCount}
              </span>
            )}
          </div>
          <span>Cart</span>
        </NavLink>

        <NavLink
          to="/profile"
          className={({ isActive }) => `mobile-nav-btn ${isActive ? 'active' : ''}`}
        >
          <i className="bi bi-person-fill"></i>
          <span>Profile</span>
        </NavLink>
      </div>
    </nav>
  );
}

export default BottomNav;
