import React, { useState } from 'react';
import { useCart } from '../context/CartContext';
import { useWishlist } from '../context/WishlistContext';
import ProductQuickView from './ProductQuickView';

function ProductCard({ product }) {
  const { addToCart } = useCart();
  const { isInWishlist, toggleWishlist } = useWishlist();

  const [addedAnimation, setAddedAnimation] = useState(false);
  const [showQuickView, setShowQuickView] = useState(false);

  const isWished = isInWishlist(product.id);

  const handleAddToCart = (e) => {
    e.stopPropagation();
    addToCart(product);
    setAddedAnimation(true);
    setTimeout(() => {
      setAddedAnimation(false);
    }, 1500);
  };

  const handleWishlistClick = (e) => {
    e.stopPropagation();
    toggleWishlist(product);
  };

  const discountPercent =
    product.discountPercent ||
    (product.originalPrice
      ? Math.round(((product.originalPrice - product.price) / product.originalPrice) * 100)
      : 0);

  return (
    <>
      <div className="product-card-igp" onClick={() => setShowQuickView(true)}>
        <div className="product-card-image-wrap">
          <img
            src={product.image}
            alt={product.name}
            loading="lazy"
          />

          {/* Status Badge */}
          {product.badge && (
            <span className="card-status-badge">{product.badge}</span>
          )}

          {/* Wishlist Toggle Button */}
          <button
            type="button"
            className={`card-wishlist-btn ${isWished ? 'active' : ''}`}
            onClick={handleWishlistClick}
            aria-label={isWished ? 'Remove from wishlist' : 'Add to wishlist'}
          >
            <i className={`bi bi-heart${isWished ? '-fill text-danger' : ''}`}></i>
          </button>

          {/* Quick View Button */}
          <button
            type="button"
            className="card-quickview-btn"
            onClick={(e) => {
              e.stopPropagation();
              setShowQuickView(true);
            }}
          >
            <i className="bi bi-eye me-1"></i> Quick View
          </button>
        </div>

        <div className="product-card-details">
          <div className="d-flex justify-content-between align-items-center mb-1">
            <span className="product-card-category">{product.category}</span>
            {product.rating && (
              <span className="product-card-rating">
                <i className="bi bi-star-fill text-warning"></i> {product.rating}
              </span>
            )}
          </div>

          <h3 className="product-card-title" title={product.name}>
            {product.name}
          </h3>

          {product.deliveryBadge && (
            <div className="card-delivery-badge mb-2">
              <i className="bi bi-lightning-charge-fill"></i> {product.deliveryBadge}
            </div>
          )}

          {/* Price Row */}
          <div className="product-card-price-row">
            <span className="product-card-current-price">
              ₹{product.price.toLocaleString('en-IN')}
            </span>
            {product.originalPrice && (
              <span className="product-card-original-price">
                ₹{product.originalPrice.toLocaleString('en-IN')}
              </span>
            )}
            {discountPercent > 0 && (
              <span className="product-card-discount">
                ({discountPercent}% OFF)
              </span>
            )}
          </div>

          {/* Add to Bag CTA */}
          <button
            type="button"
            className={`product-card-add-btn ${addedAnimation ? 'added-state' : ''}`}
            onClick={handleAddToCart}
          >
            {addedAnimation ? (
              <>
                <i className="bi bi-check-circle-fill"></i>
                <span>Added to Bag</span>
              </>
            ) : (
              <>
                <i className="bi bi-bag-plus"></i>
                <span>Add to Bag</span>
              </>
            )}
          </button>
        </div>
      </div>

      {/* Quick View Modal */}
      <ProductQuickView
        product={product}
        show={showQuickView}
        onHide={() => setShowQuickView(false)}
      />
    </>
  );
}

export default ProductCard;
