import React from 'react';
import { Carousel, Container } from 'react-bootstrap';
import { Link } from 'react-router-dom';

const HERO_SLIDES = [
  {
    id: 1,
    tag: 'Handcrafted With Love',
    headline: 'Make Every Moment Unforgettable',
    subtext: 'Thoughtful gifts, personal touches, and little surprises that mean everything. Delivered across 400+ cities in India.',
    primaryCta: 'Explore Gifts',
    primaryLink: '/products',
    secondaryCta: 'Find the Perfect Gift',
    secondaryLink: '#gift-finder',
    image: 'https://images.unsplash.com/photo-1513519245088-0e12902e5a38?auto=format&fit=crop&w=1600&q=80'
  },
  {
    id: 2,
    tag: 'Romantic Celebrations',
    headline: 'Anniversary & Couple Keepsakes',
    subtext: '3D Lunar Moon Lamps, personalized star maps, and Belgian gourmet chocolate hampers crafted to celebrate love.',
    primaryCta: 'Shop Anniversary',
    primaryLink: '/products?category=Anniversary',
    secondaryCta: 'View Bestsellers',
    secondaryLink: '/products',
    image: 'https://images.unsplash.com/photo-1518199266791-5375a83190b7?auto=format&fit=crop&w=1600&q=80'
  },
  {
    id: 3,
    tag: 'Farm-Fresh Blooms Daily',
    headline: 'Fresh Flowers & Gourmet Truffle Cakes',
    subtext: 'Express 2-hour hand delivery & midnight surprises for birthdays and celebratory moments that cannot wait.',
    primaryCta: 'Send Flowers & Cakes',
    primaryLink: '/products?category=Flowers',
    secondaryCta: 'Order for Today',
    secondaryLink: '/products?category=Cakes',
    image: 'https://images.unsplash.com/photo-1561181286-d3fee7d55364?auto=format&fit=crop&w=1600&q=80'
  }
];

function HeroCarousel() {
  const scrollToFinder = (e) => {
    e.preventDefault();
    const el = document.getElementById('gift-finder-section');
    if (el) {
      el.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <section className="hero-section py-2 py-md-3">
      <Container fluid="lg" className="max-w-1440 px-2 px-md-3">
        <Carousel
          indicators={true}
          interval={5000}
          className="hero-carousel-container"
          aria-label="Promotional Carousel"
        >
          {HERO_SLIDES.map((slide) => (
            <Carousel.Item key={slide.id}>
              <div
                className="hero-slide-wrapper"
                style={{ backgroundImage: `url(${slide.image})` }}
              >
                <div className="hero-slide-overlay"></div>
                <div className="hero-slide-content text-white">
                  <span className="badge-pill-gold mb-2 d-inline-block text-uppercase">
                    {slide.tag}
                  </span>
                  <h1 className="display-6 display-md-5 fw-bold font-serif mb-2 text-white">
                    {slide.headline}
                  </h1>
                  <p className="lead fs-6 mb-4 text-white-50">
                    {slide.subtext}
                  </p>
                  <div className="d-flex flex-wrap gap-2.5">
                    <Link to={slide.primaryLink} className="btn btn-champagne">
                      {slide.primaryCta}
                    </Link>
                    {slide.secondaryLink.startsWith('#') ? (
                      <a
                        href={slide.secondaryLink}
                        onClick={scrollToFinder}
                        className="btn btn-outline-light rounded-2 fw-semibold px-4 py-2"
                      >
                        {slide.secondaryCta}
                      </a>
                    ) : (
                      <Link
                        to={slide.secondaryLink}
                        className="btn btn-outline-light rounded-2 fw-semibold px-4 py-2"
                      >
                        {slide.secondaryCta}
                      </Link>
                    )}
                  </div>
                </div>
              </div>
            </Carousel.Item>
          ))}
        </Carousel>
      </Container>
    </section>
  );
}

export default HeroCarousel;
