import React from 'react';
import { Container, Row, Col } from 'react-bootstrap';
import { Link } from 'react-router-dom';
import ProductCard from './ProductCard';

function ProductSection({
  title,
  subtitle,
  categoryFilter,
  products = [],
  viewAllLink = '/products',
  tag,
  bgClass = ''
}) {
  if (!products.length) return null;

  return (
    <section className={`py-4 py-md-5 ${bgClass}`}>
      <Container fluid="lg" className="max-w-1440 px-2 px-md-3">
        <div className="d-flex align-items-end justify-content-between mb-3 mb-md-4">
          <div>
            {tag && (
              <span className="extra-small text-uppercase fw-bold text-primary-berry tracking-wider">
                {tag}
              </span>
            )}
            <h2 className="fs-3 fw-bold font-serif text-dark mb-0">{title}</h2>
            {subtitle && <p className="extra-small text-muted mb-0">{subtitle}</p>}
          </div>
          <Link
            to={viewAllLink || (categoryFilter ? `/products?category=${encodeURIComponent(categoryFilter)}` : '/products')}
            className="small fw-bold text-primary-berry text-decoration-none"
          >
            View All →
          </Link>
        </div>

        <Row xs={2} sm={2} md={3} lg={4} className="g-2 g-md-3 g-lg-4">
          {products.slice(0, 4).map((product) => (
            <Col key={product.id}>
              <ProductCard product={product} />
            </Col>
          ))}
        </Row>
      </Container>
    </section>
  );
}

export default ProductSection;
