import React, { useState } from 'react';
import { Modal, Row, Col, Button, Form, Badge } from 'react-bootstrap';
import { useCart } from '../context/CartContext';
import { useWishlist } from '../context/WishlistContext';

function ProductQuickView({ product, show, onHide }) {
  const { addToCart } = useCart();
  const { isInWishlist, toggleWishlist } = useWishlist();

  const [quantity, setQuantity] = useState(1);
  const [personalizationText, setPersonalizationText] = useState('');
  const [addedSuccess, setAddedSuccess] = useState(false);

  if (!product) return null;

  const isWished = isInWishlist(product.id);

  const handleAddToCart = () => {
    addToCart({
      ...product,
      customNote: personalizationText || undefined,
      quantity
    });
    setAddedSuccess(true);
    setTimeout(() => {
      setAddedSuccess(false);
      onHide();
    }, 1200);
  };

  return (
    <Modal show={show} onHide={onHide} size="lg" centered className="modern-dialog">
      <Modal.Header closeButton className="border-0 pb-0"></Modal.Header>
      <Modal.Body className="p-4 pt-0">
        <Row className="g-4 align-items-center">
          <Col md={6}>
            <div className="rounded-3 overflow-hidden border position-relative" style={{ aspectRatio: '1/1' }}>
              <img
                src={product.image}
                alt={product.name}
                className="w-100 h-100 object-fit-cover"
              />
              {product.badge && (
                <span className="card-status-badge">{product.badge}</span>
              )}
            </div>
          </Col>

          <Col md={6}>
            <div className="product-card-category">{product.category}</div>
            <h4 className="fw-bold mb-2 font-serif text-dark">{product.name}</h4>

            {/* Rating & Review */}
            <div className="d-flex align-items-center gap-2 mb-3">
              <span className="product-card-rating">
                <i className="bi bi-star-fill"></i> {product.rating}
              </span>
              <span className="extra-small text-muted">({product.reviewsCount} reviews)</span>
              {product.deliveryBadge && (
                <Badge bg="success-subtle" text="success" className="border border-success-subtle extra-small ms-auto">
                  <i className="bi bi-truck me-1"></i> {product.deliveryBadge}
                </Badge>
              )}
            </div>

            {/* Price */}
            <div className="d-flex align-items-baseline gap-2 mb-3">
              <span className="fs-3 fw-bold text-dark font-serif">
                ₹{product.price.toLocaleString('en-IN')}
              </span>
              {product.originalPrice && (
                <span className="text-muted text-decoration-line-through">
                  ₹{product.originalPrice.toLocaleString('en-IN')}
                </span>
              )}
              {product.discountPercent > 0 && (
                <span className="fw-bold text-danger small">
                  ({product.discountPercent}% OFF)
                </span>
              )}
            </div>

            <p className="small text-muted mb-3">{product.description}</p>

            {/* Personalization live note */}
            {product.isPersonalizable && (
              <div className="mb-3 p-2.5 bg-light rounded-3 border">
                <Form.Label className="extra-small fw-bold text-uppercase text-dark mb-1">
                  ✍️ Add Custom Personalization (Optional)
                </Form.Label>
                <Form.Control
                  type="text"
                  placeholder="e.g. Rahul & Sneha • 14 Feb 2026"
                  size="sm"
                  value={personalizationText}
                  onChange={(e) => setPersonalizationText(e.target.value)}
                />
              </div>
            )}

            {/* Quantity Modifier */}
            <div className="d-flex align-items-center gap-3 mb-4">
              <span className="small fw-semibold text-muted">Quantity:</span>
              <div className="d-flex align-items-center border rounded-pill px-2 py-1 bg-light">
                <button
                  type="button"
                  className="btn btn-sm btn-link text-dark text-decoration-none p-0 px-2 fw-bold"
                  onClick={() => setQuantity(Math.max(1, quantity - 1))}
                >
                  -
                </button>
                <span className="px-2 fw-bold small">{quantity}</span>
                <button
                  type="button"
                  className="btn btn-sm btn-link text-dark text-decoration-none p-0 px-2 fw-bold"
                  onClick={() => setQuantity(quantity + 1)}
                >
                  +
                </button>
              </div>
            </div>

            {/* Actions */}
            <div className="d-flex gap-2">
              <Button
                className={`flex-grow-1 fw-bold py-2.5 rounded-3 text-uppercase ${
                  addedSuccess ? 'btn-success' : 'btn-primary-berry'
                }`}
                onClick={handleAddToCart}
                disabled={addedSuccess}
              >
                {addedSuccess ? (
                  <>
                    <i className="bi bi-check-circle-fill me-2"></i> Added to Bag
                  </>
                ) : (
                  <>
                    <i className="bi bi-bag-plus me-2"></i> Add to Bag
                  </>
                )}
              </Button>

              <Button
                variant={isWished ? 'danger' : 'outline-secondary'}
                className="rounded-3 px-3"
                onClick={() => toggleWishlist(product)}
                title={isWished ? 'Remove from Wishlist' : 'Add to Wishlist'}
              >
                <i className={`bi bi-heart${isWished ? '-fill' : ''}`}></i>
              </Button>
            </div>
          </Col>
        </Row>
      </Modal.Body>
    </Modal>
  );
}

export default ProductQuickView;
