import React, { useState } from 'react';
import { Container, Row, Col, Form, Button, Alert } from 'react-bootstrap';
import { useCart } from '../context/CartContext';
import { SAMPLE_PRODUCTS } from '../data/products';

const TEMPLATES = [
  {
    id: 101,
    name: '3D Glow Lunar Moon Lamp',
    basePrice: 999,
    image: 'https://images.unsplash.com/photo-1540932239986-30128078f3c5?auto=format&fit=crop&w=600&q=80',
    mockupType: 'lamp'
  },
  {
    id: 104,
    name: 'Star Constellation & Song Frame',
    basePrice: 799,
    image: 'https://images.unsplash.com/photo-1513542789411-b6a5d4f31634?auto=format&fit=crop&w=600&q=80',
    mockupType: 'frame'
  },
  {
    id: 111,
    name: 'Magic Temperature Ceramic Mug',
    basePrice: 399,
    image: 'https://images.unsplash.com/photo-1514432324607-a09d9b4aefdd?auto=format&fit=crop&w=600&q=80',
    mockupType: 'mug'
  }
];

function PersonalizationStudio() {
  const { addToCart } = useCart();
  const [selectedTemplate, setSelectedTemplate] = useState(TEMPLATES[0]);
  const [customName, setCustomName] = useState('Rahul & Sneha');
  const [customDate, setCustomDate] = useState('14 February 2026');
  const [customSong, setCustomSong] = useState('Kesariya (Arijit Singh)');
  const [addedSuccess, setAddedSuccess] = useState(false);

  const handleAddToCart = () => {
    const matchedProduct = SAMPLE_PRODUCTS.find((p) => p.id === selectedTemplate.id) || {
      id: selectedTemplate.id,
      name: selectedTemplate.name,
      price: selectedTemplate.basePrice,
      image: selectedTemplate.image,
      category: 'Personalized Gifts'
    };

    addToCart({
      ...matchedProduct,
      customNote: `Engraving: "${customName}" | Date: ${customDate} | Special Note: ${customSong}`
    });

    setAddedSuccess(true);
    setTimeout(() => {
      setAddedSuccess(false);
    }, 2500);
  };

  return (
    <section className="py-4 py-md-5">
      <Container fluid="lg" className="max-w-1440 px-2 px-md-3">
        <div className="personalization-studio-card">
          <Row className="g-4 align-items-center">
            {/* Live Interactive Preview Surface */}
            <Col lg={6}>
              <div className="live-preview-surface">
                <div className="d-flex align-items-center justify-content-between mb-3">
                  <span className="badge bg-dark text-white rounded-pill extra-small px-3 py-1.5">
                    ✨ Real-Time Mockup Studio
                  </span>
                  <span className="extra-small text-muted fst-italic">
                    *Illustrative 3D engraving preview
                  </span>
                </div>

                {/* Simulated Laser Engraved Mockup Frame */}
                <div
                  className="live-preview-mockup-frame"
                  style={{
                    backgroundImage: `linear-gradient(rgba(30, 10, 20, 0.7), rgba(40, 15, 25, 0.85)), url(${selectedTemplate.image})`,
                    backgroundSize: 'cover',
                    backgroundPosition: 'center'
                  }}
                >
                  <div className="text-center p-3">
                    <div className="extra-small text-uppercase tracking-wider opacity-75 mb-1" style={{ color: 'var(--champagne-accent)' }}>
                      {selectedTemplate.mockupType === 'lamp' ? '🌕 Laser Engraved Keepsake' : '⭐ Constellation Memory'}
                    </div>
                    <div className="live-engraved-text mb-1">
                      {customName || 'Your Names Here'}
                    </div>
                    <div className="extra-small text-white-50 mb-2">
                      {customDate || 'Special Date'}
                    </div>
                    <div className="badge bg-white text-dark rounded-pill extra-small px-2.5 py-1">
                      🎵 {customSong || 'Favorite Melody / Note'}
                    </div>
                  </div>
                </div>

                <div className="d-flex justify-content-between align-items-center pt-2">
                  <div className="text-start">
                    <span className="extra-small text-muted d-block">Handcrafted for you</span>
                    <span className="fw-bold font-serif fs-5 text-dark">
                      ₹{selectedTemplate.basePrice.toLocaleString('en-IN')}
                    </span>
                  </div>
                  <span className="extra-small text-success fw-bold">
                    <i className="bi bi-shield-check me-1"></i> 100% Quality Inspected
                  </span>
                </div>
              </div>
            </Col>

            {/* Customization Inputs */}
            <Col lg={6}>
              <div className="ps-lg-3">
                <span className="badge-pill-gold text-uppercase mb-2 d-inline-block">
                  Personalization Studio
                </span>
                <h2 className="fs-3 fw-bold font-serif text-dark mb-2">
                  Add Your Special Touch
                </h2>
                <p className="text-muted small mb-4">
                  Transform custom lamps, star map frames, and memory mugs into emotional treasures with precision laser engraving.
                </p>

                {addedSuccess && (
                  <Alert variant="success" className="py-2 small mb-3">
                    🎉 Customized keepsake added to your Shopping Bag with engraving notes!
                  </Alert>
                )}

                {/* Template Selector */}
                <div className="mb-3">
                  <Form.Label className="small fw-bold text-dark mb-1.5">
                    1. Choose Keepsake Style
                  </Form.Label>
                  <div className="d-flex flex-wrap gap-2">
                    {TEMPLATES.map((tmpl) => (
                      <button
                        key={tmpl.id}
                        type="button"
                        className={`btn btn-sm rounded-pill px-3 py-1.5 extra-small fw-semibold border ${
                          selectedTemplate.id === tmpl.id
                            ? 'btn-primary-berry'
                            : 'btn-light text-dark'
                        }`}
                        onClick={() => setSelectedTemplate(tmpl)}
                      >
                        {tmpl.name} (₹{tmpl.basePrice})
                      </button>
                    ))}
                  </div>
                </div>

                {/* Name Input */}
                <Form.Group className="mb-3">
                  <Form.Label className="small fw-bold text-dark mb-1">
                    2. Recipient Name(s) to Engrave
                  </Form.Label>
                  <Form.Control
                    type="text"
                    placeholder="e.g. Rahul & Sneha"
                    value={customName}
                    onChange={(e) => setCustomName(e.target.value)}
                    maxLength={32}
                  />
                </Form.Group>

                {/* Date & Occasion Input */}
                <Row className="g-2 mb-3">
                  <Col sm={6}>
                    <Form.Group>
                      <Form.Label className="small fw-bold text-dark mb-1">
                        3. Celebration Date
                      </Form.Label>
                      <Form.Control
                        type="text"
                        placeholder="e.g. 14 February 2026"
                        value={customDate}
                        onChange={(e) => setCustomDate(e.target.value)}
                        maxLength={24}
                      />
                    </Form.Group>
                  </Col>
                  <Col sm={6}>
                    <Form.Group>
                      <Form.Label className="small fw-bold text-dark mb-1">
                        4. Spotify Song / Note
                      </Form.Label>
                      <Form.Control
                        type="text"
                        placeholder="e.g. Kesariya"
                        value={customSong}
                        onChange={(e) => setCustomSong(e.target.value)}
                        maxLength={32}
                      />
                    </Form.Group>
                  </Col>
                </Row>

                <Button
                  className="btn-primary-berry w-100 py-2.5 fw-bold text-uppercase shadow-sm"
                  onClick={handleAddToCart}
                >
                  <i className="bi bi-gift-fill me-2"></i> Add Customized Keepsake to Bag (₹{selectedTemplate.basePrice})
                </Button>
              </div>
            </Col>
          </Row>
        </div>
      </Container>
    </section>
  );
}

export default PersonalizationStudio;
