import React, { useState } from 'react';

const ANNOUNCEMENTS = [
  { text: '🌸 FESTIVE CELEBRATION: Free Express Delivery on orders above ₹499 | Code: FESTIVE10', tag: 'Offer' },
  { text: '⚡ Order by 5 PM for Same Day Delivery across 400+ Indian Cities', tag: 'Fast Delivery' },
  { text: '🎁 Handcrafted with Love: Free velvet ribbon gift packaging & greeting card', tag: 'Artisan' }
];

function AnnouncementBar() {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isVisible, setIsVisible] = useState(true);

  if (!isVisible) return null;

  const handleNext = () => {
    setCurrentIndex((prev) => (prev + 1) % ANNOUNCEMENTS.length);
  };

  const handlePrev = () => {
    setCurrentIndex((prev) => (prev - 1 + ANNOUNCEMENTS.length) % ANNOUNCEMENTS.length);
  };

  const current = ANNOUNCEMENTS[currentIndex];

  return (
    <div className="announcement-bar py-1.5 px-3">
      <div className="container-fluid max-w-1440 d-flex align-items-center justify-content-between">
        <button
          type="button"
          onClick={handlePrev}
          className="btn btn-link text-white text-decoration-none p-0 d-none d-md-inline"
          aria-label="Previous announcement"
          style={{ opacity: 0.7 }}
        >
          <i className="bi bi-chevron-left small"></i>
        </button>

        <div className="d-flex align-items-center justify-content-center gap-2 text-center flex-grow-1">
          <span className="badge-pill-gold d-none d-sm-inline">{current.tag}</span>
          <span className="small fw-semibold">{current.text}</span>
        </div>

        <div className="d-flex align-items-center gap-2">
          <button
            type="button"
            onClick={handleNext}
            className="btn btn-link text-white text-decoration-none p-0 d-none d-md-inline"
            aria-label="Next announcement"
            style={{ opacity: 0.7 }}
          >
            <i className="bi bi-chevron-right small"></i>
          </button>
          <button
            type="button"
            onClick={() => setIsVisible(false)}
            className="btn btn-link text-white text-decoration-none p-0 ms-2"
            aria-label="Dismiss announcement"
            style={{ opacity: 0.7 }}
          >
            <i className="bi bi-x-lg small"></i>
          </button>
        </div>
      </div>
    </div>
  );
}

export default AnnouncementBar;
