import React from 'react';
import { Link } from 'react-router-dom';
import { Row, Col, Container } from 'react-bootstrap';
import { MEGA_MENU_DATA } from '../data/products';

function MegaMenu({ activeCategory, onClose }) {
  const menuData = MEGA_MENU_DATA[activeCategory];
  if (!menuData) return null;

  return (
    <div className="mega-menu-popover" onMouseLeave={onClose}>
      <Container fluid="lg" className="max-w-1440">
        <Row className="g-4">
          {menuData.columns.map((col, idx) => (
            <Col key={idx} md={3}>
              <div className="mega-menu-col-title">{col.title}</div>
              <div className="d-flex flex-column gap-1">
                {col.links.map((linkName, linkIdx) => (
                  <Link
                    key={linkIdx}
                    to="/products"
                    className="mega-menu-link"
                    onClick={onClose}
                  >
                    {linkName}
                  </Link>
                ))}
              </div>
            </Col>
          ))}

          {menuData.featuredPromo && (
            <Col md={3}>
              <div className="p-3 bg-light rounded-3 border text-center h-100 d-flex flex-column justify-content-between">
                <div>
                  <div className="rounded-3 overflow-hidden mb-2" style={{ aspectRatio: '16/9' }}>
                    <img
                      src={menuData.featuredPromo.image}
                      alt={menuData.featuredPromo.title}
                      className="w-100 h-100 object-fit-cover"
                    />
                  </div>
                  <h6 className="fw-bold text-dark font-serif mb-1">{menuData.featuredPromo.title}</h6>
                  <p className="extra-small text-muted mb-2">{menuData.featuredPromo.description}</p>
                </div>
                <Link
                  to="/products"
                  className="btn btn-sm btn-outline-berry rounded-pill w-100 fw-bold extra-small"
                  onClick={onClose}
                >
                  Explore Collection
                </Link>
              </div>
            </Col>
          )}
        </Row>
      </Container>
    </div>
  );
}

export default MegaMenu;
