import React from 'react';
import HeroCarousel from '../components/HeroCarousel';
import OccasionsGrid from '../components/OccasionsGrid';
import GiftFinder from '../components/GiftFinder';
import ProductSection from '../components/ProductSection';
import PersonalizationStudio from '../components/PersonalizationStudio';
import TrustSection from '../components/TrustSection';
import EditorialSection from '../components/EditorialSection';
import { SAMPLE_PRODUCTS } from '../data/products';

function Home() {
  const bestsellers = SAMPLE_PRODUCTS.filter(
    (p) => p.badge === 'Bestseller' || p.rating >= 4.9
  );

  const flowersAndCakes = SAMPLE_PRODUCTS.filter(
    (p) => p.category === 'Flowers' || p.category === 'Cakes'
  );

  const luxuryHampers = SAMPLE_PRODUCTS.filter(
    (p) => p.category === 'Gift Hampers' || p.category === 'Offers'
  );

  const budgetFriendly = SAMPLE_PRODUCTS.filter((p) => p.price <= 999);

  const personalizedPicks = SAMPLE_PRODUCTS.filter((p) => p.isPersonalizable);

  return (
    <div className="home-page pb-5 pb-lg-0">
      {/* 1. Hero Carousel Banner */}
      <HeroCarousel />

      {/* 2. Shop by Occasion Grid */}
      <OccasionsGrid />

      {/* 3. Interactive Gift Finder */}
      <GiftFinder />

      {/* 4. Bestsellers Collection */}
      <ProductSection
        tag="Top Rated Customer Favorites"
        title="Most Loved Bestsellers"
        subtitle="The highest rated celebratory surprises across India"
        products={bestsellers}
        viewAllLink="/products"
      />

      {/* 5. Live Personalization Studio */}
      <PersonalizationStudio />

      {/* 6. Fresh Flowers & Gourmet Cakes Collection */}
      <ProductSection
        tag="Fresh Express Delivery"
        title="Farm-Fresh Blooms & Artisanal Cakes"
        subtitle="Handcrafted daily with same-day and midnight delivery options"
        products={flowersAndCakes}
        categoryFilter="Flowers"
        bgClass="bg-white border-top border-bottom"
      />

      {/* 7. Curated Personalized Gifts */}
      <ProductSection
        tag="Handmade Keepsakes"
        title="Trending Personalized Gifts"
        subtitle="Laser-engraved names, constellation star maps & customized Spotify frames"
        products={personalizedPicks}
        categoryFilter="Personalized Gifts"
      />

      {/* 8. Luxury Hampers & Combos */}
      <ProductSection
        tag="Celebration Trunks"
        title="Artisan Gift Hampers & Combos"
        subtitle="Loaded with gourmet chocolates, honey, candles & pine wooden keepsakes"
        products={luxuryHampers}
        categoryFilter="Gift Hampers"
        bgClass="bg-white border-top border-bottom"
      />

      {/* 9. Pocket-Friendly Curations */}
      <ProductSection
        tag="Affordable Surprises"
        title="Thoughtful Gifts Under ₹999"
        subtitle="Celebrate every bond without compromising on craftsmanship"
        products={budgetFriendly}
        viewAllLink="/products"
      />

      {/* 10. Delivery & Trust Guarantees */}
      <TrustSection />

      {/* 11. Editorial Inspiration & Guides */}
      <EditorialSection />
    </div>
  );
}

export default Home;
